import{_ as t,c as e,o as a,V as i}from"./chunks/framework.B6I5AJO8.js";const u=JSON.parse('{"title":"nb06 · Qdrant index & evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"research/qdrant-index-eval.md","filePath":"research/qdrant-index-eval.md"}'),r={name:"research/qdrant-index-eval.md"},d=i('<h1 id="nb06-·-qdrant-index-evaluation" tabindex="-1">nb06 · Qdrant index &amp; evaluation <a class="header-anchor" href="#nb06-·-qdrant-index-evaluation" aria-label="Permalink to &quot;nb06 · Qdrant index &amp; evaluation&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb06_qdrant_index_and_eval.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-objective" tabindex="-1">The objective <a class="header-anchor" href="#the-objective" aria-label="Permalink to &quot;The objective&quot;">​</a></h2><p>nb05 selected <code>Qwen3-Embedding-0.6B</code>. This notebook builds a real Qdrant vector store from that model, verifies that persisted retrieval reproduces nb05&#39;s in-memory results, and compares Qdrant against two alternative stores on identical vectors. It connects the offline benchmark to the production retrieval pipeline: same corpus, same chunks, same embeddings, a real storage backend.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Collection <code>kalisio_qwen3_nb06_v1</code>, Qdrant at <code>localhost:6333</code>, model <code>Qwen/Qwen3-Embedding-0.6B</code>, cosine distance, 1024-dim vectors.</p><h2 id="corpus" tabindex="-1">Corpus <a class="header-anchor" href="#corpus" aria-label="Permalink to &quot;Corpus&quot;">​</a></h2><p>The same scope as nb05: 1,251 files, 9,893 chunks.</p><table><thead><tr><th>Repository</th><th style="text-align:right;">Chunks</th><th></th><th>Chunk type</th><th style="text-align:right;">Chunks</th></tr></thead><tbody><tr><td>kdk</td><td style="text-align:right;">6,497</td><td></td><td>js (javascript)</td><td style="text-align:right;">3,908</td></tr><tr><td>crisis</td><td style="text-align:right;">1,930</td><td></td><td>md (markdown)</td><td style="text-align:right;">1,846</td></tr><tr><td>kano</td><td style="text-align:right;">648</td><td></td><td>vue (script)</td><td style="text-align:right;">1,733</td></tr><tr><td>kapp</td><td style="text-align:right;">492</td><td></td><td>json (i18n)</td><td style="text-align:right;">842</td></tr><tr><td>skeleton</td><td style="text-align:right;">326</td><td></td><td>vue (template)</td><td style="text-align:right;">681</td></tr><tr><td></td><td style="text-align:right;"></td><td></td><td>json (schemas)</td><td style="text-align:right;">222</td></tr></tbody></table><h2 id="index-build" tabindex="-1">Index build <a class="header-anchor" href="#index-build" aria-label="Permalink to &quot;Index build&quot;">​</a></h2><p>All 9,893 chunks were encoded with Qwen3 and upserted into Qdrant (1024-dim, cosine). The collection holds 9,893 points; encoding and building took ~117 s, with the Qdrant upsert itself at ~1,069 chunks/sec. A manifest records the index version, model, distance and counts.</p><h2 id="gold-set-retrieval-against-the-persisted-store" tabindex="-1">Gold-set retrieval against the persisted store <a class="header-anchor" href="#gold-set-retrieval-against-the-persisted-store" aria-label="Permalink to &quot;Gold-set retrieval against the persisted store&quot;">​</a></h2><p>The nb05 200-question gold set was replayed against the real Qdrant collection, using the same Qwen3 query prefix and de-duplicating chunks into file-level rankings. <code>hit@5</code>:</p><table><thead><tr><th>Layer</th><th style="text-align:right;">EN</th><th style="text-align:right;">FR</th></tr></thead><tbody><tr><td>A_symbol</td><td style="text-align:right;">0.883</td><td style="text-align:right;">0.883</td></tr><tr><td>B_docs</td><td style="text-align:right;">0.725</td><td style="text-align:right;">0.688</td></tr><tr><td>C_code</td><td style="text-align:right;">0.733</td><td style="text-align:right;">0.511</td></tr><tr><td>negative</td><td style="text-align:right;">0.000</td><td style="text-align:right;">0.000</td></tr></tbody></table><p>Overall <code>hit@5</code> is 0.778 (EN) and 0.708 (FR).</p><h2 id="consistency-with-the-nb05-in-memory-benchmark" tabindex="-1">Consistency with the nb05 in-memory benchmark <a class="header-anchor" href="#consistency-with-the-nb05-in-memory-benchmark" aria-label="Permalink to &quot;Consistency with the nb05 in-memory benchmark&quot;">​</a></h2><p>The persisted Qdrant results match nb05&#39;s in-memory Qwen3 evaluation. The only material difference is EN <code>C_code</code> (nb05 0.756 vs Qdrant 0.733), with small <code>hit@1</code> shifts (A_symbol EN 0.500 → 0.533) — consistent with Qdrant&#39;s approximate-nearest-neighbour index. No prefix, normalization, distance or payload-mapping discrepancy was observed.</p><table><thead><tr><th>Layer (EN)</th><th style="text-align:right;">nb05 in-memory</th><th style="text-align:right;">Qdrant</th></tr></thead><tbody><tr><td>A_symbol</td><td style="text-align:right;">0.883</td><td style="text-align:right;">0.883</td></tr><tr><td>B_docs</td><td style="text-align:right;">0.725</td><td style="text-align:right;">0.725</td></tr><tr><td>C_code</td><td style="text-align:right;">0.756</td><td style="text-align:right;">0.733</td></tr></tbody></table><h2 id="vector-store-comparison" tabindex="-1">Vector-store comparison <a class="header-anchor" href="#vector-store-comparison" aria-label="Permalink to &quot;Vector-store comparison&quot;">​</a></h2><p>The same vectors were loaded into Chroma and LanceDB and evaluated on the same gold set. Retrieval quality is identical across the three stores; they differ only in timing.</p><table><thead><tr><th>Store</th><th style="text-align:right;">hit@5</th><th style="text-align:right;">hit@10</th><th style="text-align:right;">MRR</th><th style="text-align:right;">Query time (200 queries)</th></tr></thead><tbody><tr><td>Qdrant</td><td style="text-align:right;">0.743</td><td style="text-align:right;">0.851</td><td style="text-align:right;">0.511</td><td style="text-align:right;">6.7 s</td></tr><tr><td>Chroma</td><td style="text-align:right;">0.743</td><td style="text-align:right;">0.851</td><td style="text-align:right;">0.511</td><td style="text-align:right;">8.0 s</td></tr><tr><td>LanceDB</td><td style="text-align:right;">0.746</td><td style="text-align:right;">0.851</td><td style="text-align:right;">0.511</td><td style="text-align:right;">55.1 s</td></tr></tbody></table><p>Per-language <code>hit@5</code> is the same across stores (EN 0.778, FR 0.708–0.714). Build time was 1.0 s for LanceDB and 8.1 s for Chroma (Qdrant reused its already-built collection). Qdrant has the lowest query time in this run and reproduces the nb05 benchmark, so it remains the reference store; the choice of store does not change retrieval quality.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>Negative-query safety is weak for every store</strong> — the <code>negative</code> layer scores 0% safety at <code>hit@5</code> / <code>hit@10</code>: for out-of-scope queries the retriever still returns its nearest chunks. This is a property of the retrieval policy, not the vector store, and is addressed in the reranking / abstention layer rather than by changing databases.</li><li>The gold set is the nb05 200-question set, mined from and evaluated on the same corpus, so <code>hit@k</code> measures within-corpus retrieval rather than generalization.</li></ul>',24),n=[d];function s(o,l,h,c,g,y){return a(),e("div",null,n)}const b=t(r,[["render",s]]);export{u as __pageData,b as default};
